CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE workspaces(id uuid PRIMARY KEY,mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
CREATE TABLE sources(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,revision integer NOT NULL CHECK(revision>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE source_revisions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,source_id uuid NOT NULL,revision integer NOT NULL,title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 120),text text NOT NULL CHECK(char_length(text) BETWEEN 100 AND 20000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,revision),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE manuals(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,source_id uuid NOT NULL,source_revision_id uuid NOT NULL,draft jsonb NOT NULL,draft_revision integer NOT NULL DEFAULT 1,published_version integer,needs_review boolean NOT NULL DEFAULT false,provenance text NOT NULL CHECK(provenance IN ('ai','human','example')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,source_revision_id) REFERENCES source_revisions(workspace_id,id));
CREATE TABLE manual_versions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,manual_id uuid NOT NULL,version integer NOT NULL,source_revision_id uuid NOT NULL,content jsonb NOT NULL,provenance text NOT NULL,acknowledged_unknowns jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(manual_id,version),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,manual_id) REFERENCES manuals(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,source_revision_id) REFERENCES source_revisions(workspace_id,id));
ALTER TABLE manuals ADD CONSTRAINT published_version_fk FOREIGN KEY(id,published_version) REFERENCES manual_versions(manual_id,version) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE shares(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,manual_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,manual_id) REFERENCES manuals(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE sessions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,role text NOT NULL CHECK(role IN ('owner','reader')),share_id uuid,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,share_id) REFERENCES shares(workspace_id,id) ON DELETE CASCADE,CHECK((role='owner' AND share_id IS NULL) OR (role='reader' AND share_id IS NOT NULL)));
CREATE TABLE question_runs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,session_id uuid NOT NULL,question text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),FOREIGN KEY(workspace_id,session_id) REFERENCES sessions(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE evidence(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,question_id uuid NOT NULL,manual_id uuid NOT NULL,manual_version_id uuid NOT NULL,source_id uuid NOT NULL,source_revision_id uuid NOT NULL,paragraph_id text NOT NULL,quote text NOT NULL,kind text NOT NULL CHECK(kind IN ('manual','source')),FOREIGN KEY(workspace_id,question_id) REFERENCES question_runs(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,manual_id) REFERENCES manuals(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,manual_version_id) REFERENCES manual_versions(workspace_id,id),FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id),FOREIGN KEY(workspace_id,source_revision_id) REFERENCES source_revisions(workspace_id,id));
CREATE TABLE operation_requests(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,session_id uuid NOT NULL,key text NOT NULL,payload_hash text NOT NULL,kind text NOT NULL CHECK(kind IN ('generate','question')),status text NOT NULL CHECK(status IN ('processing','complete','failed')),result jsonb,error_code text,lease_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,key));
CREATE TABLE usage_counters(day date NOT NULL,scope text NOT NULL,kind text NOT NULL,attempts integer NOT NULL DEFAULT 0,PRIMARY KEY(day,scope,kind));
CREATE TABLE rate_counters(key text PRIMARY KEY,attempts integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX source_text_trgm ON source_revisions USING gin(text gin_trgm_ops);
CREATE INDEX workspace_expiry ON workspaces(expires_at);
CREATE INDEX evidence_question ON evidence(question_id);
CREATE FUNCTION forbid_snapshot_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Snapshots are immutable'; END $$;
CREATE TRIGGER immutable_source BEFORE UPDATE ON source_revisions FOR EACH ROW EXECUTE FUNCTION forbid_snapshot_update();
CREATE TRIGGER immutable_manual BEFORE UPDATE ON manual_versions FOR EACH ROW EXECUTE FUNCTION forbid_snapshot_update();
